import os
import pytest
from isort.setuptools_commands import ISortCommand

class MockDistribution:
    def __init__(self, packages=None, package_dir=None, py_modules=None):
        self.packages = packages or []
        self.package_dir = package_dir or {}
        self.py_modules = py_modules or []

def test_distribution_files_with_packages():
    command = ISortCommand()
    command.distribution = MockDistribution(
        packages=['mypackage'],
        package_dir={'mypackage': 'src/mypackage'}
    )

    expected_files = [
        'src/mypackage',
        'setup.py'
    ]

    assert list(command.distribution_files()) == expected_files

def test_distribution_files_with_py_modules():
    command = ISortCommand()
    command.distribution = MockDistribution(
        py_modules=['mymodule']
    )

    expected_files = [
        'mymodule.py',
        'setup.py'
    ]

    assert list(command.distribution_files()) == expected_files

def test_distribution_files_with_empty_distribution():
    command = ISortCommand()
    command.distribution = MockDistribution()

    expected_files = ['setup.py']

    assert list(command.distribution_files()) == expected_files

import pytest
from isort._vendored.tomli._parser import Flags

class TestFlags:
    @pytest.fixture
    def flags_instance(self):
        # Create an instance of Flags with a predefined structure for testing
        flags = Flags()
        flags._flags = {
            'level1': {
                'nested': {
                    'level2': {
                        'flags': [1, 2, 3],
                        'recursive_flags': [4]
                    }
                },
                'recursive_flags': []
            }
        }
        return flags

    def test_is_with_none_key(self, flags_instance):
        assert not flags_instance.is_(None, 1)

    def test_is_with_empty_key(self, flags_instance):
        assert not flags_instance.is_([], 1)

    def test_is_with_missing_nested_key(self, flags_instance):
        assert not flags_instance.is_(["level1", "level2", "missing"], 1)

    def test_is_with_key_in_flags(self, flags_instance):
        assert flags_instance.is_(["level1", "level2"], 1)

    def test_is_with_key_in_recursive_flags(self, flags_instance):
        assert flags_instance.is_(["level1", "level2"], 4)

    def test_is_with_key_in_flags_not_present(self, flags_instance):
        assert not flags_instance.is_(["level1", "level2"], 5)

import os
import pytest
from isort.deprecated.finders import ReqsBaseFinder

class TestReqsBaseFinder:

    @pytest.fixture
    def setup_finder(self):
        """Fixture to create a ReqsBaseFinder instance for testing."""
        finder = ReqsBaseFinder()
        finder.path = '/fake/path/to/requirements'  # Set a fake path
        return finder

    @pytest.mark.parametrize("test_input, expected", [
        ("/fake/path/to/requirements/requirements.txt", ["/fake/path/to/requirements"]),
        ("/fake/path/to/requirements/extra-requirements.txt", ["/fake/path/to/requirements"]),
    ])
    def test_get_files_with_file_path(self, setup_finder, test_input, expected):
        setup_finder.path = test_input
        result = list(setup_finder._get_files())
        assert sorted(result) == sorted(expected)

    def test_get_files_with_directory_path(self, setup_finder, monkeypatch):
        # Mock the behavior of _get_parents and _get_files_from_dir
        def mock_get_parents(path):
            return ["/fake/path/to/requirements"]

        def mock_get_files_from_dir(path):
            return iter(["/fake/path/to/requirements/requirements.txt"])

        monkeypatch.setattr(setup_finder, "_get_parents", mock_get_parents)
        monkeypatch.setattr(setup_finder, "_get_files_from_dir", mock_get_files_from_dir)

        setup_finder.path = '/fake/path/to/requirements'
        result = list(setup_finder._get_files())
        assert result == ["/fake/path/to/requirements/requirements.txt"]

import pytest
from isort.format import format_simplified

def test_format_simplified_from_import():
    assert format_simplified("from module import function") == "module.function"

def test_format_simplified_import():
    assert format_simplified("import module") == "module"

def test_format_simplified_empty_string():
    assert format_simplified("   ") == ""

def test_format_simplified_no_import():
    assert format_simplified("no import statement") == "no import statement"

def test_format_simplified_extra_spaces():
    assert format_simplified("   from    module    import  function   ") == "module.function"
